dslRule:
java.lang.StringBuffer $var = new java.lang.StringBuffer($args$);
=> java.lang.StringBuilder $var = new java.lang.StringBuilder($args$);
;;

beforeExample:
public class Example {
    void foo() {
        java.lang.StringBuffer sb = new java.lang.StringBuffer("hello");
        sb.append(" world");
        System.out.println(sb.toString());
    }
    void bar(int capacity) {
        java.lang.StringBuffer buf = new java.lang.StringBuffer(capacity);
        buf.append("buffer content");
    }
}

afterExample:
public class Example {
    void foo() {
        java.lang.StringBuilder sb = new java.lang.StringBuilder("hello");
        sb.append(" world");
        System.out.println(sb.toString());
    }
    void bar(int capacity) {
        java.lang.StringBuilder buf = new java.lang.StringBuilder(capacity);
        buf.append("buffer content");
    }
}

negativeExample:
public class NegativeExample {
    private java.lang.StringBuffer fieldBuffer = new java.lang.StringBuffer("field"); // Should not match: field declaration

    void process(java.lang.StringBuffer paramBuffer) { // Should not match: method parameter
        paramBuffer.append("stuff");
    }

    void lateInit() {
        java.lang.StringBuffer tempBuffer;
        tempBuffer = new java.lang.StringBuffer("later"); // Should not match: assignment, not declaration with initializer
    }
}
